  Lemma x34_join : forall q pt' bits flag c4 bc4 mm (t2 a1 t3 t4 t5 t6 : word),
    X4F' mm SPL (BD c4 bc4 (SS + O4 + pt')) -> 0 <= q <= dcap -> 0 <= pt' -> pt' + 8 <= L4 -> 0 <= bits <= 64 ->
    (flag = 0 \/ flag = 1) ->
    (forall q' c4' bc4' pt'' mm' (t1' t2' a1' a5' t3' t4' t5' t6' : word) bits',
       X4F' mm' SPL (BD c4' bc4' (SS + O4 + pt'')) -> q + 4 <= q' <= dcap -> 0 <= pt'' -> (pt'' = 0 \/ pt'' + 8 <= L4) ->
       0 <= bits' <= 64 ->
       evt psegs POST (HD 0x1a5c0 mm' q' bits' t1' t2' a1' a5' t3' t4' t5' t6')) ->
    evt psegs POST (HD 0x1a61c mm q bits (Z_to_bv 64 flag) t2 a1 (Z_to_bv 64 (SS + O4 + pt')) t3 t4 t5 t6).
